<?php $__env->startPush('scripts'); ?><script>
(()=>{const root=document.getElementById('sections');let si=0;const sumEl=document.getElementById('marksSum'),status=document.getElementById('marksStatus'),total=document.getElementById('totalMarks');
function update(){let n=[...root.querySelectorAll('.qmark')].reduce((s,e)=>s+(parseFloat(e.value)||0),0),t=parseFloat(total.value)||0;sumEl.textContent=n.toFixed(2);status.textContent=`পূর্ণমান: ${t} | প্রশ্নের নম্বর: ${n.toFixed(2)} | ${Math.abs(n-t)<0.01?'নম্বর মিলেছে':'নম্বরের যোগফল পূর্ণমানের সমান করুন'}`;status.className='mt-2 text-sm '+(Math.abs(n-t)<0.01?'text-emerald-700':'text-rose-600')}
function addQuestion(section,idx){let qi=section.dataset.qcount||0;section.dataset.qcount=Number(qi)+1;let wrap=document.createElement('div');wrap.className='question-row rounded-lg border bg-white p-3';wrap.innerHTML=`<div class="mb-2 flex justify-between"><b class="q-label">প্রশ্ন</b><button type="button" class="remove text-sm text-rose-600">মুছুন</button></div><label class="mb-1 block text-xs font-semibold">অধ্যায় / টপিক</label><input class="field mb-2" name="sections[${idx}][questions][${qi}][topic]" placeholder="অধ্যায় / ইউনিট / টপিক"><label class="mb-1 block text-xs font-semibold">প্রশ্নের বিবরণ *</label><textarea required rows="3" class="field mb-2" name="sections[${idx}][questions][${qi}][text]" placeholder="প্রশ্ন লিখুন। উপপ্রশ্ন থাকলে ক), খ), গ) আলাদা লাইনে লিখুন।"></textarea><div class="grid gap-2 sm:grid-cols-2"><div><label class="mb-1 block text-xs font-semibold">প্রশ্নের ধরন</label><select class="field" name="sections[${idx}][questions][${qi}][type]"><option>Creative</option><option>Short</option><option>MCQ</option><option>Practical</option></select></div><div><label class="mb-1 block text-xs font-semibold">নম্বর *</label><input required type="number" min="0.25" step="0.25" value="1" class="field qmark" name="sections[${idx}][questions][${qi}][marks]"></div></div>`;wrap.querySelector('.remove').onclick=()=>{wrap.remove();renumber(section);update()};wrap.querySelector('.qmark').oninput=update;section.querySelector('.question-list').append(wrap);renumber(section);update()}
function renumber(section){section.querySelectorAll('.question-row').forEach((q,i)=>q.querySelector('.q-label').textContent=`প্রশ্ন ${i+1}`)}
function addSection(title='',instruction='',count=1,mark=1){let idx=si++,box=document.createElement('div');box.className='section-box rounded-xl border-2 border-slate-200 p-4';box.dataset.qcount='0';box.innerHTML=`<div class="mb-3 flex flex-wrap items-center justify-between gap-2"><b class="section-label">বিভাগ</b><button type="button" class="remove-section text-sm font-semibold text-rose-600">বিভাগ মুছুন</button></div><div class="grid gap-3 md:grid-cols-2"><div><label class="mb-1 block text-sm font-semibold">বিভাগের নাম *</label><input required class="field" name="sections[${idx}][title]" value="${title}" placeholder="যেমন: ক-বিভাগ (মান: ১×১০=১০)"></div><div><label class="mb-1 block text-sm font-semibold">এই বিভাগের নির্দেশনা</label><input class="field" name="sections[${idx}][instruction]" value="${instruction}" placeholder="যেমন: সকল প্রশ্নের উত্তর দাও"></div></div><div class="question-list mt-3 space-y-3"></div><button type="button" class="add-question mt-3 rounded-lg border border-blue-200 px-3 py-2 text-sm font-semibold text-blue-700">＋ এই বিভাগে প্রশ্ন যুক্ত করুন</button>`;box.querySelector('.add-question').onclick=()=>addQuestion(box,idx);box.querySelector('.remove-section').onclick=()=>{box.remove();update()};root.append(box);for(let k=0;k<count;k++){addQuestion(box,idx);box.querySelectorAll('.qmark')[k].value=mark}update();return box}
document.getElementById('addSection').onclick=()=>addSection('নতুন বিভাগ','');total.addEventListener('input',update);addSection('ক-বিভাগ (মান: ১×১০=১০)','সকল প্রশ্নের উত্তর দাও',10,1);addSection('খ-বিভাগ (মান: ২×১০=২০)','সকল প্রশ্নের উত্তর দাও',10,2);addSection('গ-বিভাগ (মান: ৫×৪=২০)','যে কোনো ৪টি প্রশ্নের উত্তর দাও',4,5);update();})();
